//! Android OS certificate verification for the shared HTTPS transport.
//!
//! `rustls-platform-verifier` checks certificates through Android's own
//! trust manager, which it reaches over JNI. The app calls
//! `org.foundation.wikipedia.rust.RustTls.nativeInit(context)` once at
//! startup. The JNI export, its panic guard and its exception mapping are
//! generated by `jni::native_method!`; this file has no hand-written
//! `unsafe` (guarded by scripts/test_ffi_unsafe_boundary.py).

use jni::errors::Error;
use jni::objects::{JClass, JObject};
use jni::Env;

/// Exported as `Java_org_foundation_wikipedia_rust_RustTls_nativeInit__…`.
/// The JVM resolves the export by name; registering the method is optional.
pub const NATIVE_INIT: jni::NativeMethod = jni::native_method! {
    java_type = "org.foundation.wikipedia.rust.RustTls",
    static extern fn native_init(context: JObject) -> void,
};

fn native_init<'local>(
    env: &mut Env<'local>,
    _class: JClass<'local>,
    context: JObject<'local>,
) -> Result<(), Error> {
    if context.is_null() {
        return Err(Error::NullPtr("context"));
    }
    rustls_platform_verifier::android::init_with_env(env, context)?;
    wiki_ai::hosted_http::mark_platform_verifier_ready();
    Ok(())
}
